// Runs inside a real browser against the INSTALLED packages, resolved via
// the "browser" export condition (importmap generated by smoke-browser.mjs).
// Posts every check's outcome to /report; the harness asserts the counts.
import { parse, Parser, ParseError, Quantity, Formula, Unitsdb, DimensionMismatchError } from "unitsml";
import { toXml } from "unitsml/render";
import {
  createAsciiUnits,
  parse as asciiParse,
  artifactChecksum,
  ArtifactChecksumError,
  ArtifactLoadError,
  ARTIFACT_ENVELOPE_CHECKSUM,
} from "asciiunits";

const results = [];
async function check(name, fn) {
  try {
    const detail = await fn();
    results.push({ name, ok: true, detail: detail ?? null });
  } catch (error) {
    results.push({ name, ok: false, error: `${error?.name}: ${error?.message}` });
  }
}
const expect = (cond, msg) => {
  if (!cond) throw new Error(msg);
};
async function rejectsWith(promise, Klass, pattern) {
  try {
    await promise;
  } catch (error) {
    expect(error instanceof Klass, `expected ${Klass.name}, got ${error?.name}: ${error?.message}`);
    if (pattern) expect(pattern.test(error.message), `message ${error.message} !~ ${pattern}`);
    return `${error.name}: ${error.message}`;
  }
  throw new Error(`expected rejection with ${Klass.name}`);
}
const dec = async (value, from, to) =>
  (await (await Quantity.parse(value, from)).convertTo(to)).value.toDecimalString();

// The SDK engine is a per-page singleton, so a missing engine asset can only
// be observed before anything initialized it: separate page load.
if (new URLSearchParams(location.search).get("mode") === "engine-missing") {
  await check("missing engine wasm is a load error, not null", async () =>
    rejectsWith(createAsciiUnits({ wasm: "/missing/parsanol_bg.wasm" }).parse("m"), ArtifactLoadError));
  await fetch("/report?mode=engine-missing", { method: "POST", body: JSON.stringify(results) });
  throw new Error("engine-missing mode done");
}

await check("no node/env polyfills in page", () => {
  expect(typeof globalThis.process === "undefined", "process is defined");
  expect(typeof globalThis.Buffer === "undefined", "Buffer is defined");
  expect(typeof globalThis.require === "undefined", "require is defined");
  return navigator.userAgent;
});
await check("artifact pin verified via WebCrypto", async () => {
  const sum = await artifactChecksum();
  expect(/^sha256:[0-9a-f]{64}$/.test(sum), sum);
  return { file: sum, envelope: ARTIFACT_ENVELOPE_CHECKSUM };
});
await check("embedded artifact tests green", async () => {
  const failures = await createAsciiUnits().artifactTestFailures();
  expect(Array.isArray(failures) && failures.length === 0, JSON.stringify(failures).slice(0, 300));
  return 0;
});
await check("unit parse -> Formula -> renders", async () => {
  const f = await parse("unitsml(mm*s^-2)");
  expect(f instanceof Formula, `not a Formula: ${f?.constructor?.name}`);
  const ascii = f.toAsciimath();
  expect(ascii === "mm*s^-2", ascii);
  const mathml = f.mathmlString();
  expect(/<math|<mi|<mrow|<msup/.test(mathml), mathml.slice(0, 120));
  const xml = toXml(f);
  expect(/<Unit[ >]/.test(xml) && /xml:id=/.test(xml), xml.slice(0, 200));
  return { ascii, mathmlLength: mathml.length, xmlLength: xml.length };
});
await check("quotient parse J/kg*K", async () => {
  const ascii = (await parse("unitsml(J/kg*K)")).toAsciimath();
  expect(ascii === "J/kg^-1*K^-1", ascii);
  return ascii;
});
await check("exact km->m and m->km", async () => {
  const a = await dec("1", "km", "m");
  const b = await dec("1", "m", "km");
  const c = await dec("4", "km^2", "m^2");
  expect(a === "1000" && b === "0.001" && c === "4000000", `${a} ${b} ${c}`);
  return { a, b, c };
});
await check("affine Celsius conversion", async () => {
  const a = await dec("0", "degC", "K");
  const b = await dec("20", "degC", "K");
  expect(a === "273.15" && b === "293.15", `${a} ${b}`);
  return { a, b };
});
await check("Celsius difference typing", async () => {
  const d = (await Quantity.parse("20", "degC")).minus(await Quantity.parse("15", "degC"));
  expect(d.scale === "difference", d.scale);
  const k = (await d.convertTo("K")).value.toDecimalString();
  expect(k === "5", k);
  return { scale: d.scale, k };
});
await check("quotient dimension metadata", async () => {
  const speed = await Quantity.parse("3", "m/s");
  const v = Object.fromEntries(speed.dimensionVector() ?? []);
  expect(v.Length === 1 && v.Time === -1 && Object.keys(v).length === 2, JSON.stringify(v));
  const force = (await Quantity.parse("2", "kg")).times(await Quantity.parse("3", "m/s^2"));
  const fv = Object.fromEntries(force.dimensionVector() ?? []);
  expect(fv.Length === 1 && fv.Mass === 1 && fv.Time === -2, JSON.stringify(fv));
  return { speed: v, force: fv };
});
await check("unitsdb canonical data present", () => {
  const db = Unitsdb;
  expect(db !== undefined, "Unitsdb export missing");
  return typeof db;
});
await check("dimension mismatch refused", async () =>
  rejectsWith((await Quantity.parse("1", "mi")).convertTo("s"), DimensionMismatchError));
await check("bad input refused (unitsml)", async () =>
  rejectsWith(new Parser("10m").parse(), Error, /failed to parse/));
await check("bad input refused (asciiunits null)", async () => {
  const r = await asciiParse("@@ not units");
  expect(r === null, `expected null, got ${JSON.stringify(r)}`);
  return null;
});
await check("corrupt artifact refused (served)", async () =>
  rejectsWith(createAsciiUnits({ artifact: "/corrupt/unitsml.json" }).parse("m"), ArtifactChecksumError));
await check("corrupt artifact refused (injected bytes)", async () => {
  const bytes = new Uint8Array(await (await fetch("/node_modules/asciiunits/artifacts/unitsml.json")).arrayBuffer());
  bytes[bytes.length - 2] ^= 1;
  return rejectsWith(createAsciiUnits({ artifact: bytes }).parse("m"), ArtifactChecksumError);
});
await check("missing artifact asset is a load error, not null", async () => {
  const au = createAsciiUnits({ artifact: "/missing/unitsml.json" });
  const first = await rejectsWith(au.parse("m"), ArtifactLoadError, /HTTP 404/);
  await rejectsWith(au.parseShape("m"), ArtifactLoadError, /HTTP 404/);
  return first;
});
await check("isolated injected-bytes runtime parses", async () => {
  const bytes = await (await fetch("/node_modules/asciiunits/artifacts/unitsml.json")).arrayBuffer();
  const tree = await createAsciiUnits({ artifact: () => Promise.resolve(bytes) }).parse("km");
  expect(tree?.constructor?.name === "Unit" && tree.unitName === "m", JSON.stringify(tree));
  return tree.prefix?.prefixName;
});

await fetch("/report", { method: "POST", body: JSON.stringify(results) });
